607	    /// @return unsafeDestination True when the address is known same-factory protocol plumbing.
608	    function _isProtocolDestination(address destination, address prizeToken_)
609	        private
610	        view
611	        returns (bool unsafeDestination)
612	    {
613	        IRaffleFactory canonicalFactory = IRaffleFactory(factory);
614	        unsafeDestination = destination == address(this) || destination == factory || destination == address(quoteToken)
615	            || destination == address(i_vrfV2PlusWrapper) || destination == prizeToken_
616	            || destination == canonicalFactory.raffleImplementation();
617	        if (!unsafeDestination && destination.code.length != 0) {
618	            unsafeDestination = canonicalFactory.isRaffle(destination);
