541	    // Private state-changing helpers
542	
543	    /// @dev Validates the winning range once and allocates all terminal quote-token liabilities without transferring
544	    ///      an asset or reading ticket ownership. Both percentage allocations round down; sponsor proceeds are the
545	    ///      remainder.
546	    /// @param ticketId Ticket whose inclusive range must contain the selected winning entry.
547	    /// @return cashAmount Raw six-decimal quote-token units allocated to the cash winner, or zero for `NftWon`.
548	    function _settleWinningTicket(uint256 ticketId) private returns (uint256 cashAmount) {
549	        if (settlementComplete) revert SettlementAlreadyComplete();
550	        Status result = status;
551	        if (result != Status.NftWon && result != Status.CashWon) revert InvalidStatus(result);
552	
553	        _requireWinningTicket(ticketId);
554	        uint256 grossPot = unsettledPot;
555	        uint256 protocolFee = Math.mulDiv(grossPot, RaffleConstants.PROTOCOL_FEE_BPS, RaffleConstants.BPS);
556	        uint256 sponsorAmount;
557	
558	        if (result == Status.NftWon) {
559	            sponsorAmount = grossPot - protocolFee;
560	        } else {
561	            cashAmount = Math.mulDiv(grossPot, RaffleConstants.CASH_WINNER_BPS, RaffleConstants.BPS);
562	            sponsorAmount = grossPot - protocolFee - cashAmount;
563	            winnerProceeds = cashAmount;
564	        }
565	
566	        settlementComplete = true;
567	        winningTicketId = ticketId;
568	        unsettledPot = 0;
569	        sponsorProceeds = sponsorAmount;
570	        protocolFees = protocolFee;
571	
572	        emit WinningTicketSettled(ticketId, msg.sender, result, cashAmount, protocolFee, sponsorAmount);
573	    }
574	
575	    /// @dev Transfers one complete current USDC claim through SafeERC20 after rejecting known protocol sinks. The
576	    ///      canonical USDC trust model assumes standard, non-rebasing, fee-free transfer semantics.
577	    /// @param to Immutable or owner-derived recipient of the claim.
578	    /// @param amount Raw six-decimal USDC units transferred.
579	    function _transferQuote(address to, uint256 amount) private {
580	        if (_isProtocolDestination(to, address(prizeToken))) revert InvalidQuoteDestination(to);
581	        quoteToken.safeTransfer(to, amount);
582	    }
583	
584	    // Private view and pure helpers
585	
586	    /// @dev Reverts unless the raffle is in the expected lifecycle state.
587	    /// @param expected Status required by the calling operation.
588	    function _requireStatus(Status expected) private view {
589	        if (status != expected) revert InvalidStatus(status);
590	    }
591	
592	    /// @dev Reverts unless the supplied ticket's stored inclusive range contains the selected winning entry.
593	    /// @param ticketId Candidate winning ticket ID.
594	    function _requireWinningTicket(uint256 ticketId) private view {
