import { ERC721 } from "@openzeppelin/contracts/token/ERC721/ERC721.sol";

interface Vm {
    function warp(uint256) external;
    function roll(uint256) external;
    function prank(address) external;
    function startPrank(address) external;
    function stopPrank() external;
    function deal(address, uint256) external;
    function expectRevert() external;
    function expectRevert(bytes4) external;
    function expectRevert(bytes calldata) external;
    function txGasPrice(uint256) external;
    function getNonce(address) external view returns (uint64);
    function computeCreateAddress(address deployer, uint256 nonce) external pure returns (address);
    function label(address, string calldata) external;
    function addr(uint256) external pure returns (address);
    function store(address, bytes32, bytes32) external;
    function load(address, bytes32) external view returns (bytes32);
}

contract TestBase {
    Vm internal constant vm = Vm(address(uint160(uint256(keccak256("hevm cheat code")))));

    function assertEq(uint256 a, uint256 b, string memory m) internal pure {
        if (a != b) revert(string.concat(m, " a=", _u(a), " b=", _u(b)));
    }

    function assertEqA(address a, address b, string memory m) internal pure {
        if (a != b) revert(m);
    }

    function assertTrue(bool c, string memory m) internal pure {
        if (!c) revert(m);
    }

    function _u(uint256 v) internal pure returns (string memory) {
        if (v == 0) return "0";
        uint256 j = v;
        uint256 len;
        while (j != 0) {
            len++;
            j /= 10;
        }
        bytes memory b = new bytes(len);
        while (v != 0) {
            len--;
            b[len] = bytes1(uint8(48 + v % 10));
            v /= 10;
        }
        return string(b);
    }
}

contract MockUSDC {
    string public name = "USD Coin";
    string public symbol = "USDC";
    uint8 public constant decimals = 6;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amt) external {
        balanceOf[to] += amt;
        totalSupply += amt;
    }

    function approve(address s, uint256 a) external returns (bool) {
        allowance[msg.sender][s] = a;
        return true;
    }

    function transfer(address to, uint256 a) external returns (bool) {
        balanceOf[msg.sender] -= a;
        balanceOf[to] += a;
        return true;
    }

    function transferFrom(address f, address to, uint256 a) external returns (bool) {
        uint256 al = allowance[f][msg.sender];
        if (al != type(uint256).max) allowance[f][msg.sender] = al - a;
        balanceOf[f] -= a;
        balanceOf[to] += a;
        return true;
    }
}

interface IRawFulfill {
    function rawFulfillRandomWords(uint256, uint256[] memory) external;
}

/// @dev Behavioural model of VRFV2PlusWrapper native direct funding: price uses tx.gasprice, callback uses exact gas,
///      a failed callback is swallowed and the request is consumed.
contract MockVRFWrapper {
    struct Callback {
        address callbackAddress;
        uint32 callbackGasLimit;
    }

    address public link = address(0x1111);
    address public linkNativeFeed = address(0x2222);
    uint256 public lastRequestId;
    uint256 public nonce;
    uint256 public constant OVERHEAD = 13_400;
    uint256 public constant FLAT = 1e12 * 500; // 0.0005 ETH
    mapping(uint256 => Callback) public callbacks;
    uint256 public lastCallbackGasUsed;
    bool public lastSuccess;

    function calculateRequestPrice(uint32, uint32) external pure returns (uint256) {
        return 0;
    }

    function estimateRequestPrice(uint32, uint32, uint256) external pure returns (uint256) {
        return 0;
    }

    function calculateRequestPriceNative(uint32 gasLimit, uint32) public view returns (uint256) {
        return tx.gasprice * (uint256(gasLimit) + OVERHEAD) + FLAT;
    }

    function estimateRequestPriceNative(uint32 gasLimit, uint32, uint256 gp) external pure returns (uint256) {
        return gp * (uint256(gasLimit) + OVERHEAD) + FLAT;
    }

    function requestRandomWordsInNative(uint32 gasLimit, uint16, uint32, bytes calldata extraArgs)
        external
        payable
        returns (uint256 requestId)
    {
        require(extraArgs.length >= 36 && extraArgs[35] == hex"01", "native mode");
        require(msg.value >= calculateRequestPriceNative(gasLimit, 1), "fee too low");
        requestId = uint256(keccak256(abi.encode(msg.sender, ++nonce)));
        callbacks[requestId] = Callback(msg.sender, gasLimit);
        lastRequestId = requestId;
    }

    function fulfill(uint256 requestId, uint256 word) external returns (bool success) {
        Callback memory c = callbacks[requestId];
        delete callbacks[requestId];
        require(c.callbackAddress != address(0), "request not found");
        uint256[] memory words = new uint256[](1);
        words[0] = word;
        bytes memory resp = abi.encodeWithSelector(IRawFulfill.rawFulfillRandomWords.selector, requestId, words);
        uint256 g0 = gasleft();
        address target = c.callbackAddress;
        uint256 gl = c.callbackGasLimit;
        assembly {
            success := call(gl, target, 0, add(resp, 0x20), mload(resp), 0, 0)
        }
        lastCallbackGasUsed = g0 - gasleft();
        lastSuccess = success;
    }
}

contract MockNFT is ERC721 {
    constructor() ERC721("Prize", "PRZ") { }

    function mint(address to, uint256 id) external {
        _mint(to, id);
    }
}

