pragma solidity 0.8.36;

import { TestBase, MockUSDC, MockVRFWrapper, MockNFT } from "./utils/Base.sol";
import { Raffle } from "../src/Raffle.sol";
import { RaffleFactory } from "../src/RaffleFactory.sol";
import { IRaffle } from "../src/interfaces/IRaffle.sol";
import { IRaffleFactory } from "../src/interfaces/IRaffleFactory.sol";

contract LifecycleTest is TestBase {
    MockUSDC usdc;
    MockVRFWrapper wrapper;
    MockNFT nft;
    RaffleFactory factory;
    address treasury = address(0x7EA5);
    address sponsor = address(0x5905);
    address sponsorRecipient = address(0x5906);
    address alice = address(0xA11CE);
    address bob = address(0xB0B);

    function setUp() public {
        vm.warp(1_700_000_000);
        usdc = new MockUSDC();
        wrapper = new MockVRFWrapper();
        nft = new MockNFT();
        factory = new RaffleFactory(address(usdc), address(wrapper), treasury);
        nft.mint(sponsor, 1);
        usdc.mint(alice, 1_000_000e6);
        usdc.mint(bob, 1_000_000e6);
    }

    function _create(uint128 reserve) internal returns (Raffle r) {
        vm.startPrank(sponsor);
        nft.approve(address(factory), 1);
        r = Raffle(
            payable(factory.createRaffle(
                    IRaffleFactory.CreateRaffleParams({
                        sponsorRecipient: sponsorRecipient,
                        prizeToken: address(nft),
                        prizeTokenId: 1,
                        reserveEntries: reserve,
                        endTime: uint64(block.timestamp + 1 days)
                    })
                ))
        );
        vm.stopPrank();
    }

    function _buy(Raffle r, address who, uint128 n) internal returns (uint256 id) {
        vm.startPrank(who);
        usdc.approve(address(r), type(uint256).max);
        id = r.buyEntries(who, n);
        vm.stopPrank();
    }

    function _draw(Raffle r) internal returns (uint256 reqId) {
        vm.warp(r.endTime());
        vm.txGasPrice(10 gwei);
        vm.deal(address(this), 10 ether);
        reqId = r.requestDraw{ value: 1 ether }();
    }

    receive() external payable { }

    function test_nftWon() public {
        Raffle r = _create(10);
        uint256 t1 = _buy(r, alice, 6);
        uint256 t2 = _buy(r, bob, 4);
        uint256 req = _draw(r);
        wrapper.fulfill(req, 7); // 7 % 10 + 1 = 8 -> bob (entries 7..10)
        assertTrue(wrapper.lastSuccess(), "cb ok");
        assertEq(wrapper.lastCallbackGasUsed(), 0, "gas used by callback (info)");
    }
}

