import { IRaffle } from "../src/interfaces/IRaffle.sol";
import { IRaffleFactory } from "../src/interfaces/IRaffleFactory.sol";

contract LifecycleTest is TestBase {
    MockUSDC usdc;
    MockVRFWrapper wrapper;
    MockNFT nft;
    RaffleFactory factory;
    address treasury = address(0x7EA5);
    address sponsor = address(0x5905);
    address sponsorRecipient = address(0x5906);
    address alice = address(0xA11CE);
    address bob = address(0xB0B);
    address carol = address(0xCA201);

    function setUp() public {
        vm.warp(1_700_000_000);
        usdc = new MockUSDC();
        wrapper = new MockVRFWrapper();
        nft = new MockNFT();
        factory = new RaffleFactory(address(usdc), address(wrapper), treasury);
        nft.mint(sponsor, 1);
        nft.mint(sponsor, 2);
        usdc.mint(alice, 1_000_000e6);
        usdc.mint(bob, 1_000_000e6);
        usdc.mint(carol, 1_000_000e6);
    }

    function _create(uint256 id, address recipient, uint128 reserve) internal returns (Raffle r) {
        vm.startPrank(sponsor);
        nft.approve(address(factory), id);
        r = Raffle(
            payable(factory.createRaffle(
                    IRaffleFactory.CreateRaffleParams({
                        sponsorRecipient: recipient,
                        prizeToken: address(nft),
                        prizeTokenId: id,
                        reserveEntries: reserve,
                        endTime: uint64(block.timestamp + 1 days)
                    })
                ))
        );
        vm.stopPrank();
    }

    function _buy(Raffle r, address who, uint128 n) internal returns (uint256 id) {
        vm.startPrank(who);
        usdc.approve(address(r), type(uint256).max);
        id = r.buyEntries(who, n);
        vm.stopPrank();
    }

    function _draw(Raffle r) internal returns (uint256 reqId) {
        vm.warp(r.endTime());
        vm.txGasPrice(10 gwei);
        vm.deal(address(this), 10 ether);
        reqId = r.requestDraw{ value: 1 ether }();
    }

    receive() external payable { }

    function test_nftWon_accounting() public {
        Raffle r = _create(1, sponsorRecipient, 10);
        _buy(r, alice, 6);
        uint256 t2 = _buy(r, bob, 4);
        uint256 req = _draw(r);
        wrapper.fulfill(req, 7); // 7 % 10 + 1 = 8 -> bob (entries 7..10)
        assertTrue(wrapper.lastSuccess(), "cb ok");
        assertTrue(r.status() == IRaffle.Status.NftWon, "nftwon");
        r.settleWinningTicket(t2);
        r.releaseSponsorProceeds();
        r.releaseProtocolFees();
        vm.prank(bob);
        r.redeemWinningTicket(t2);
        assertEqA(nft.ownerOf(1), bob, "bob nft");
        assertEq(usdc.balanceOf(sponsorRecipient), 9_500_000, "sponsor 95%");
        assertEq(usdc.balanceOf(treasury), 500_000, "treasury 5%");
        assertEq(usdc.balanceOf(address(r)), 0, "empty");
        assertEq(r.accountedQuoteBalance(), 0, "acct");
    }

    function test_cashWon_accounting() public {
        Raffle r = _create(1, sponsorRecipient, 100);
        uint256 t1 = _buy(r, alice, 6);
        _buy(r, bob, 4);
        uint256 req = _draw(r);
        wrapper.fulfill(req, 2); // 3 -> alice
        assertTrue(r.status() == IRaffle.Status.CashWon, "cashwon");
        r.releaseSponsorPrize();
        assertEqA(nft.ownerOf(1), sponsorRecipient, "prize back");
        vm.prank(alice);
        r.redeemWinningTicket(t1);
        r.releaseSponsorProceeds();
        r.releaseProtocolFees();
        assertEq(usdc.balanceOf(address(r)), 0, "empty");
        assertEq(usdc.balanceOf(sponsorRecipient), 1_500_000, "15%");
        assertEq(usdc.balanceOf(treasury), 500_000, "5%");
    }

    function test_refund_after_callback_timeout_and_late_callback_ignored() public {
        Raffle r = _create(1, sponsorRecipient, 10);
        uint256 t1 = _buy(r, alice, 6);
        uint256 t2 = _buy(r, bob, 4);
        uint256 req = _draw(r);
        vm.warp(r.callbackDeadline());
        r.enableRefunds();
        wrapper.fulfill(req, 1); // late
        assertTrue(r.status() == IRaffle.Status.Refunding, "still refunding");
        uint256[] memory ids = new uint256[](1);
        ids[0] = t1;
        vm.prank(alice);
        r.refundTickets(ids);
        ids[0] = t2;
        vm.prank(bob);
        r.refundTickets(ids);
        r.releaseSponsorPrize();
        assertEq(usdc.balanceOf(address(r)), 0, "empty");
        assertEq(r.remainingRefundLiability(), 0, "liab");
    }

    /// Tickets stay transferable while the VRF fulfillment is pending; the winning entry is a pure function of the
    /// random word, so whoever sees the word first can pick the winning ticket and take it before the callback lands.
    function test_ticket_transfer_while_drawing() public {
        Raffle r = _create(1, sponsorRecipient, 10);
        _buy(r, alice, 6);
        uint256 t2 = _buy(r, bob, 4);
        uint256 req = _draw(r);
        uint256 word = 7; // visible in the pending fulfillment calldata
        uint256 predicted = word % r.totalEntries() + 1;
        (uint128 f, uint128 l) = r.ticketRange(t2);
        assertTrue(predicted >= f && predicted <= l, "attacker identifies winner pre-callback");
        // Bob's resting marketplace order executes: modelled as a direct transfer in Drawing state.
        vm.prank(bob);
        r.transferFrom(bob, carol, t2);
        wrapper.fulfill(req, word);
        vm.prank(carol);
        r.redeemWinningTicket(t2);
        assertEqA(nft.ownerOf(1), carol, "attacker got prize");
    }

    /// sponsorRecipient set to the factory's next CREATE address: init check passes (no code yet), later that address
    /// becomes a registered clone and releaseSponsorPrize moves the NFT into another raffle clone (no runtime check).
    function test_prize_moves_between_clones() public {
        uint64 n = vm.getNonce(address(factory));
        address nextClone = vm.computeCreateAddress(address(factory), n + 1);
        Raffle a = _create(1, nextClone, 10);
        Raffle b = _create(2, sponsorRecipient, 10);
        assertEqA(address(b), nextClone, "prediction");
        assertTrue(factory.isRaffle(address(b)), "b registered");
        // Empty raffle: sponsor cancels and anyone releases the prize.
        vm.prank(sponsor);
        a.enableRefunds();
        a.releaseSponsorPrize();
        assertEqA(nft.ownerOf(1), address(b), "prize now inside clone b");
    }
}

