pragma solidity 0.8.36;

import { Vm, MockUSDC, MockVRFWrapper, MockNFT, IRawFulfill } from "./Mocks.sol";
import { RaffleFactory } from "../src/RaffleFactory.sol";
import { IRaffleFactory } from "../src/interfaces/IRaffleFactory.sol";
import { IRaffle } from "../src/interfaces/IRaffle.sol";
import { IERC721 } from "@openzeppelin/contracts/token/ERC721/IERC721.sol";

contract GasMeasuringWrapper is MockVRFWrapper {
    uint256 public lastGasUsed;

    function fulfillMeasured(uint256 id, uint256 word) external {
        uint256[] memory words = new uint256[](1);
        words[0] = word;
        uint256 g0 = gasleft();
        IRawFulfill(consumerOf[id]).rawFulfillRandomWords{ gas: 300_000 }(id, words);
        lastGasUsed = g0 - gasleft();
    }
}

contract ExtraTest {
    Vm constant vm = Vm(address(uint160(uint256(keccak256("hevm cheat code")))));

    MockUSDC usdc;
    GasMeasuringWrapper wrapper;
    MockNFT nft;
    RaffleFactory factory;
    address treasury = address(0xFEE);
    address sponsor = address(0x5905);
    address buyer = address(0xB0B);

    function setUp() public {
        vm.warp(1_700_000_000);
        usdc = new MockUSDC();
        wrapper = new GasMeasuringWrapper();
        nft = new MockNFT();
        factory = new RaffleFactory(address(usdc), address(wrapper), treasury);
        nft.mint(sponsor, 1);
        nft.mint(sponsor, 2);
        usdc.mint(buyer, 1_000e6);
        vm.prank(sponsor);
        nft.setApprovalForAll(address(factory), true);
    }

    function _create(address recipient, uint256 id, uint128 reserve) internal returns (address) {
        vm.prank(sponsor);
        return factory.createRaffle(
            IRaffleFactory.CreateRaffleParams({
                sponsorRecipient: recipient,
                prizeToken: address(nft),
                prizeTokenId: id,
                reserveEntries: reserve,
                endTime: uint64(block.timestamp + 1 days)
            })
        );
    }

    /// Ticket variant: a ticket sent to a code-less future clone address passes `_update`; a deployed one does not.
    function test_ticketToFutureCloneThenOwnedByRaffle() public {
        address a = _create(sponsor, 1, 1);
        uint64 n = vm.getNonce(address(factory));
        address predictedB = vm.computeCreateAddress(address(factory), n);

        vm.startPrank(buyer);
        usdc.approve(a, type(uint256).max);
        uint256 t1 = IRaffle(a).buyEntries(buyer, 1);
        uint256 t2 = IRaffle(a).buyEntries(buyer, 1);
        IERC721(a).transferFrom(buyer, predictedB, t1); // passes: code.length == 0
        vm.stopPrank();

        address b = _create(sponsor, 2, 1);
        require(b == predictedB && factory.isRaffle(b), "B registered");
        require(IERC721(a).ownerOf(t1) == b, "raffle clone B owns a ticket of A");

        vm.prank(buyer);
        (bool ok,) = a.call(abi.encodeWithSelector(IERC721.transferFrom.selector, buyer, b, t2));
        require(!ok, "same transfer to the deployed clone is rejected");
    }

    /// Callback gas: confirm the VRF callback stays far below the 300,000 limit in a cold clone.
    function test_callbackGas() public {
        address a = _create(sponsor, 1, 5);
        vm.startPrank(buyer);
        usdc.approve(a, type(uint256).max);
        IRaffle(a).buyEntries(buyer, 3);
        vm.stopPrank();
        vm.warp(IRaffle(a).endTime());
        vm.deal(address(this), 1 ether);
        uint256 rid = IRaffle(a).requestDraw{ value: 0.01 ether }();
        wrapper.fulfillMeasured(rid, 12345);
        require(IRaffle(a).status() == IRaffle.Status.CashWon, "resolved");
        require(wrapper.lastGasUsed() < 100_000, "callback gas under 100k");
    }

    receive() external payable { }
}

